# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, B, A, V, R, G, DN, F, K, Y = "Lucas", "Borja", "Amparo", "Vicente", "Ramón", "Alejandra", "Daniel", "Faisal", "Min-seo", "Yu-na"
D = [
("#", "Escena 1 · 8:10 · Despacho de exportación, Onda", "장면 1 · 오전 8시 10분 · 온다, 수출팀 사무실"),
(None, "Lunes 22 de junio. Dos días después de la junta familiar. El despacho huele a café recién hecho. En la pared, el mapa del mundo: chinchetas rojas en Monterrey, amarillas en Miami y Texas, azul en Bogotá, verde en Riad y, desde mayo, morada en Seúl. Debajo de la chincheta roja, cementado en la pared, el trozo de baldosa de 1958. Lucas marca un número de Madrid.", "6월 22일 월요일. 가족 주주총회가 끝나고 이틀 뒤. 사무실에 갓 내린 커피 냄새가 난다. 벽에는 세계 지도. 몬테레이에 빨간 압정, 마이애미와 텍사스에 노란 압정, 보고타에 파란 압정, 리야드에 초록 압정, 그리고 5월부터는 서울에 보라색 압정. 빨간 압정 아래 벽에는 1958년 타일 조각이 시멘트로 박혀 있다. 루카스가 마드리드 번호를 누른다."),
(B, "Lucas. Esperaba tu llamada el viernes, no el lunes.", "루카스. 금요일에 전화할 줄 알았는데, 월요일이네."),
(L, "Buenos días, Borja. Quería esperar a la junta del sábado. Y quería dormir dos noches antes de llamarte.", "안녕하세요, 보르하. 토요일 주주총회를 기다리고 싶었어요. 그리고 전화하기 전에 이틀 밤은 자고 싶었고요."),
(B, "Eso suena a un no. Pero prefiero oírtelo decir.", "거절처럼 들리는데. 그래도 네 입으로 듣고 싶군."),
(L, "Es un no. Te agradezco la oferta, de verdad. Pero he decidido quedarme.", "거절입니다. 제안은 정말 감사해요. 하지만 남기로 결정했어요."),
(B, "¿Has leído bien las cifras? El sueldo, el bonus, la participación en el fondo... En Madrid nadie te ofrecería eso.", "숫자는 제대로 읽었어? 연봉, 보너스, 펀드 지분… 마드리드에서 아무도 너한테 그런 조건은 안 줄 거야."),
(L, "Las he leído tres veces. Son buenas cifras. El problema no son las cifras.", "세 번 읽었어요. 좋은 숫자예요. 문제는 숫자가 아니에요."),
(B, "Entonces, ¿cuál es el problema?", "그럼 뭐가 문제지?"),
(L, "Que la familia votó el sábado. Sesenta y cinco contra treinta y cinco. Albalat no se vende.", "가족이 토요일에 투표했어요. 65 대 35. 알발라트는 팔리지 않아요."),
(B, "Lo sé. Xavier me llamó esa misma noche. Pero las juntas cambian, Lucas. Con otra crisis de gas, dentro de un año volverán a votar.", "알아. 하비에르가 그날 밤 전화했어. 그런데 주주총회는 바뀌는 거야, 루카스. 가스 위기가 한 번 더 오면 1년 뒤에 또 투표하겠지."),
(L, "Puede ser. Y si vuelven a votar, quiero estar dentro de la sala, no fuera con una oferta en la mano.", "그럴지도요. 다시 투표한다면 저는 그 방 안에 있고 싶어요. 제안서를 들고 밖에 서 있는 게 아니라."),
(B, "(pausa) Hace dos años, Vicente nos dijo que no. Ahora me lo dices tú. Es la primera vez que pierdo una operación dos veces con la misma empresa.", "(잠시 멈췄다가) 2년 전엔 비센테가 우리한테 거절했지. 이번엔 네가 거절하고. 같은 회사한테 거래를 두 번 놓치는 건 처음이야."),
(L, "Hace dos años yo estaba en tu lado de la mesa. Hice el Excel de l'Alcora, ¿te acuerdas?", "2년 전엔 제가 당신 쪽 테이블에 앉아 있었죠. 라스알코라 엑셀을 제가 만들었잖아요, 기억나요?"),
(B, "Me acuerdo. Fue un buen trabajo técnico.", "기억해. 기술적으로 훌륭한 작업이었지."),
(L, "Fue un buen trabajo técnico y ciento ochenta personas a la calle. Desde entonces me comprometí a una cosa: no volver a hacer números sin mirar a la gente a la cara.", "기술적으로 훌륭했고, 180명이 길거리에 나앉았죠. 그 뒤로 저는 한 가지를 다짐했어요. 다시는 사람들 얼굴을 보지 않고 숫자를 만들지 않겠다고."),
(B, "Muy bonito. Pero las fábricas también cierran por no hacer números.", "멋진 말이야. 하지만 공장은 숫자를 안 따져서 문을 닫기도 해."),
(L, "Tienes razón. Por eso aquí los hacemos. Con Ramón, con Pepe y con el comité. Tardamos más, pero salen mejor.", "맞아요. 그래서 여기서도 숫자를 따져요. 라몬하고, 페페하고, 노조 위원회하고 같이요. 더 오래 걸리지만 더 잘 나와요."),
(B, "¿Y tú qué ganas quedándote? ¿Un despacho con vistas a un almacén?", "그래서 넌 남아서 뭘 얻는데? 창고가 내려다보이는 사무실 하나?"),
(L, "Gano un cinco por ciento de la empresa. Lo voy a pagar con mis ahorros y con un préstamo a diez años. Y gano algo que no está en tu oferta.", "회사 지분 5%를 얻어요. 제 저축이랑 10년짜리 대출로 살 거예요. 그리고 당신 제안서에는 없는 걸 얻죠."),
(B, "¿El qué?", "뭔데?"),
(L, "Saber para quién trabajo. Venga lo que venga, sabré cómo se llama cada persona que está delante de cada horno.", "누구를 위해 일하는지 아는 거요. 무슨 일이 닥치든, 가마 앞에 서 있는 사람 하나하나의 이름을 알 거예요."),
(B, "(se ríe) Siempre fuiste el más raro del equipo. Está bien, no insisto. ¿Puedo decirte algo como antiguo jefe?", "(웃으며) 넌 늘 팀에서 제일 별난 놈이었어. 좋아, 더는 조르지 않을게. 옛 상사로서 한마디 해도 될까?"),
(L, "Claro.", "물론이죠."),
(B, "Si algún día te cansas de las baldosas, mi puerta sigue abierta.", "언젠가 타일이 지겨워지면, 내 문은 계속 열려 있어."),
(L, "Te lo agradezco. Y si algún día Meridia necesita baldosas, aquí tienes un proveedor. Te debo mucho de lo que sé hacer.", "고마워요. 그리고 언젠가 메리디아에 타일이 필요하면 여기 공급업체가 있어요. 제가 할 줄 아는 것 중 많은 걸 당신한테 빚졌어요."),
(B, "(ríe) Touché. Suerte, Lucas. De verdad.", "(웃으며) 한 방 먹었네. 행운을 빌어, 루카스. 진심으로."),
(L, "Igualmente, Borja. Un abrazo.", "당신도요, 보르하. 잘 지내요."),
(None, "Lucas cuelga. Se queda un momento delante del mapa. Toca con el dedo el trozo de baldosa de 1958: el borde todavía raspa.", "루카스가 전화를 끊는다. 잠시 지도 앞에 서 있다. 손가락으로 1958년 타일 조각을 만진다. 모서리가 아직도 까끌까끌하다."),
(L, "(para sí) Seis colores y un trozo de barro. Hace dieciséis meses, en este mapa solo había Francia y Portugal.", "(혼잣말로) 여섯 가지 색깔과 흙 한 조각. 16개월 전엔 이 지도에 프랑스와 포르투갈밖에 없었는데."),

("#", "Escena 2 · 10:00 · El mismo despacho", "장면 2 · 오전 10시 · 같은 사무실"),
(None, "Amparo entra con dos cafés de la máquina. Cierra la puerta con el pie.", "암파로가 자판기 커피 두 잔을 들고 들어온다. 발로 문을 닫는다."),
(A, "¿Ya?", "벌써?"),
(L, "Ya. Le he dicho que no.", "벌써요. 거절했어요."),
(A, "¿Cómo se lo ha tomado?", "어떻게 받아들였어요?"),
(L, "Como un profesional. Me ha dicho que su puerta sigue abierta.", "프로답게요. 자기 문은 계속 열려 있다더군요."),
(A, "La de esta casa también. Pero sin bonus.", "이 집 문도 열려 있어요. 보너스는 없지만."),
(L, "Con carajillo, que es mejor.", "대신 카라히요가 있죠. 그게 더 나아요."),
(A, "(le da el café) Toma. Sin carajillo, que son las diez. Oye, quiero decirte una cosa antes de que lleguen mi padre y Ramón.", "(커피를 건네며) 자요. 카라히요는 빼고요, 10시니까. 있잖아요, 아빠랑 라몬이 오기 전에 할 말이 있어요."),
(L, "Dime.", "말해요."),
(A, "El sábado, cuando votamos, yo tenía miedo. No de perder la votación. De ganarla.", "토요일에 투표할 때 나 무서웠어요. 지는 게 아니라, 이기는 게."),
(L, "¿Por qué?", "왜요?"),
(A, "Porque si ganábamos, me tocaba a mí. Consejera delegada. Con treinta y nueve años, un hijo de once y trescientas setenta personas.", "이기면 내 차례가 되니까요. 대표이사. 서른아홉 살에, 열한 살 아들 하나에, 직원 370명."),
(L, "Te toca a ti porque te lo has ganado. No por ser la hija de Vicente.", "당신 차례가 된 건 당신이 해낼 만해서예요. 비센테의 딸이라서가 아니라."),
(A, "Eso díselo a Xavier.", "그 말은 하비에르한테 해요."),
(L, "Se lo dije el sábado. Con números.", "토요일에 했어요. 숫자로."),
(A, "Ya lo vi. (se sienta) Por eso quiero que renovemos lo nuestro.", "봤어요. (자리에 앉으며) 그래서 우리 약속을 새로 하고 싶어요."),
(L, "¿El pacto de Monterrey?", "몬테레이 약속이요?"),
(A, "El mismo. Ni clientes nuevos, ni viajes, ni promesas sin decírselo antes al otro. Pero ahora con una cláusula más.", "그거요. 새 고객도, 출장도, 약속도 상대에게 먼저 말하지 않고는 안 하기. 그런데 이번엔 조항 하나 추가."),
(L, "¿Cuál?", "뭔데요?"),
(A, "Que cuando no estemos de acuerdo, nos lo digamos a la cara antes de decírselo a nadie. Ni a mi padre.", "의견이 다를 땐 다른 누구한테 말하기 전에 서로 얼굴 보고 먼저 말하기. 아빠한테도요."),
(L, "Me comprometo. Tienes mi palabra.", "약속할게요. 내 말을 걸게요."),
(A, "Yo también me comprometo. (le tiende la mano) Socios, otra vez.", "나도 약속해요. (손을 내밀며) 다시, 동업자."),
(L, "(se la estrecha) Socios. Esta vez, con escrituras.", "(악수하며) 동업자. 이번엔 등기 서류까지 갖춰서."),
(None, "Llaman a la puerta. Entran Vicente, con una carpeta, y Ramón, con el portátil abierto.", "누군가 문을 두드린다. 서류철을 든 비센테와 노트북을 펼친 라몬이 들어온다."),
(V, "¿Interrumpimos algo?", "우리가 뭘 방해했나?"),
(A, "Nada que no podáis oír. Lucas ya ha llamado a Madrid.", "들으셔도 되는 얘기예요. 루카스가 벌써 마드리드에 전화했어요."),
(V, "¿Y?", "그래서?"),
(L, "Me quedo, Vicente.", "남습니다, 비센테."),
(V, "(se le humedecen los ojos un segundo) Ya lo sabía. Pero hay cosas que hay que oír en voz alta.", "(눈가가 잠깐 촉촉해지며) 알고 있었어. 하지만 어떤 건 소리 내서 들어야 하는 법이지."),
(R, "Bueno, vamos a lo práctico, que si no, Vicente llora. Ampliación de capital: emitimos acciones nuevas por el cinco por ciento y Lucas las suscribe a valor contable. Notario, el día treinta.", "자, 실무 얘기로 가자고. 안 그러면 비센테가 울 거야. 증자: 5%어치 신주를 발행하고 루카스가 장부가로 인수해. 공증은 30일."),
(L, "¿Y el préstamo?", "대출은요?"),
(R, "Carmen Navarro te lo aprueba esta semana. A diez años. Dice que es el primer préstamo personal que firma para comprar barro.", "카르멘 나바로가 이번 주에 승인해 줄 거야. 10년짜리. 흙 사려고 개인 대출을 내주는 건 처음이라더군."),
(V, "Barro con historia, Ramón.", "역사가 있는 흙이지, 라몬."),
(R, "Barro con historia y con un resultado que, por primera vez en cinco años, sube. Eso también ayuda al banco.", "역사가 있는 흙이고, 5년 만에 처음으로 이익이 오르는 흙이지. 그것도 은행엔 도움이 돼."),
(L, "¿Cuánto sube?", "얼마나 올랐는데요?"),
(R, "Un doce por ciento sobre el año pasado. Con Riad a pleno rendimiento, más. Pero eso no va en el comunicado: no quiero que Xavier lo lea y cambie de opinión.", "작년보다 12%. 리야드가 완전히 돌아가면 더 오르고. 하지만 그건 발표문에 안 넣어. 하비에르가 읽고 마음을 바꾸면 곤란하니까."),
(A, "Ramón, siempre pensando en todo.", "라몬은 늘 모든 걸 생각하네요."),
(V, "Bueno. Os leo el comunicado. Lo he escrito yo, así que nada de reírse.", "자. 발표문을 읽어 줄게. 내가 썼으니까 웃기 없기다."),
(A, "Papá, nadie se va a reír.", "아빠, 아무도 안 웃어요."),
(V, "(se pone las gafas y lee) «Con efecto desde el uno de julio, Amparo Albalat pasa a ser consejera delegada de Cerámicas Albalat. Lucas Ferrer, hasta ahora responsable de expansión internacional, es nombrado director general y entra en el capital de la compañía. Vicente Albalat deja la presidencia ejecutiva y pasa a ser presidente de honor.»", "(안경을 쓰고 읽는다) '7월 1일부로 암파로 알발라트가 세라미카스 알발라트의 대표이사가 된다. 지금까지 해외사업 책임자였던 루카스 페레르는 총괄 사장에 임명되며 회사 지분에 참여한다. 비센테 알발라트는 상임 회장직에서 물러나 명예회장이 된다.'"),
(R, "Correcto. Y sin artículo delante de los cargos, como debe ser.", "정확해. 직함 앞에 관사도 안 붙였고, 그래야 맞지."),
(V, "¿No es demasiado frío? Parece del Boletín Oficial.", "너무 딱딱하지 않나? 관보 같아."),
(L, "Añade una frase tuya. La que me dijiste el primer día.", "당신 말을 한 줄 넣어요. 첫날 저한테 했던 말."),
(V, "¿Cuál? Aquel día dije muchas tonterías.", "어떤 거? 그날 헛소리를 많이 했는데."),
(L, "«Vas a pisar a mucha gente. Písala con cuidado.»", "'자네는 많은 사람의 발을 밟게 될 거야. 조심해서 밟게.'"),
(V, "(ríe) Eso no lo pongo en un comunicado. Pondré otra: «La casa sigue siendo de la familia. Solo que la familia ahora es más grande.»", "(웃으며) 그건 발표문에 못 넣지. 다른 걸 넣을게. '회사는 여전히 가족의 것이다. 다만 이제 그 가족이 더 커졌을 뿐이다.'"),
(A, "Esa me gusta.", "그거 좋네요."),
(R, "A mí también. Y no cuesta dinero.", "나도. 게다가 돈도 안 들고."),
(V, "Y ahora, señor director general: la primera decisión es tuya. Ni mía, ni de Amparo.", "자 그럼, 총괄 사장님. 첫 결정은 자네 몫이야. 내 것도, 암파로 것도 아니고."),
(L, "La tengo pensada desde Seúl. Necesitamos a alguien para Asia. Corea, Singapur y lo que venga. Alguien que hable coreano, inglés y español, y que no se asuste en una nave a cuarenta grados.", "서울에서부터 생각해 둔 게 있어요. 아시아 담당이 필요해요. 한국, 싱가포르, 그리고 앞으로 생길 곳. 한국어, 영어, 스페인어를 하고, 40도짜리 공장동에서 겁먹지 않을 사람."),
(A, "¿Tienes nombre?", "이름도 있어요?"),
(L, "Han Yu-na. La mano derecha de la señora Kim. Estudió en Valencia, de Erasmus.", "한유나. 김 대표의 오른팔이에요. 발렌시아에서 교환학생을 했고요."),
(R, "¿Y la señora Kim te va a dejar que se la quites? Es su mejor persona.", "그런데 김 대표가 그 사람을 데려가게 놔두겠어? 그쪽 최고 인재잖아."),
(L, "No se la voy a quitar. Se lo voy a preguntar a ella primero. Si dice que no, buscamos a otra persona.", "데려가는 게 아니에요. 김 대표한테 먼저 물어볼 거예요. 안 된다고 하면 다른 사람을 찾고요."),
(A, "Eso es lo que acabamos de firmar, ¿no? Decirlo antes.", "그게 우리가 방금 약속한 거잖아요, 그렇죠? 먼저 말하기."),
(L, "Exacto. La llamo esta tarde, que allí ya será de noche.", "맞아요. 오늘 오후에 전화할게요. 그쪽은 벌써 밤일 테니까."),
(V, "Pues ya está. (cierra la carpeta) Comemos juntos. Y en la sobremesa hablamos de cómo se reparten los despachos.", "그럼 됐다. (서류철을 덮으며) 같이 점심 먹자. 사무실을 어떻게 나눌지는 식후 담소에서 얘기하고."),
(L, "¿Me vas a dar el tuyo?", "당신 방을 주시려고요?"),
(V, "Ni hablar. Me quedo el mío. Tú te quedas este, con tu mapa. Los presidentes de honor también necesitan una silla.", "말도 안 되지. 내 방은 내가 지켜. 자네는 이 방을 쓰게, 그 지도랑. 명예회장도 의자는 있어야지."),

("#", "Escena 3 · Martes 23 · 13:00 · El mismo despacho", "장면 3 · 23일 화요일 오후 1시 · 같은 사무실"),
(None, "Martes 23 de junio, víspera de San Juan. Esta noche habrá hogueras en la playa. El comunicado salió a las doce, y desde entonces el móvil de Lucas no ha dejado de vibrar. Amparo, sentada en la esquina de la mesa, escucha los mensajes de voz con él.", "6월 23일 화요일, 산후안 전야. 오늘 밤엔 해변에서 모닥불을 피운다. 발표문은 정오에 나갔고, 그 뒤로 루카스의 휴대폰은 쉬지 않고 진동한다. 책상 모서리에 걸터앉은 암파로가 함께 음성 메시지를 듣는다."),
(G, "(mensaje de voz) Licenciado... bueno, ya no: señor director general. Ándele, pues. Muchas felicidades. Y para que conste: la segunda fase de las torres arranca en agosto. Lo espero aquí.", "(음성 메시지) 선생님… 아, 이제 아니죠. 총괄 사장님. 잘됐네요. 정말 축하해요. 그리고 기록해 두세요. 아파트 2단계가 8월에 시작해요. 여기서 기다릴게요."),
(A, "La segunda fase. Al final ha arrancado.", "2단계. 결국 시작됐네요."),
(L, "En agosto. Y Pepe tendrá que pasar por Monterrey a la vuelta de Riad.", "8월에요. 페페는 리야드에서 돌아오는 길에 몬테레이에 들러야겠어요."),
(DN, "(mensaje de voz) ¡Gallego! ¡Director general! Mi mamá dice que lo sabía desde la cena de la ropa vieja. Y oye, chico: los pagos de Brisas, al día. Que no diga Alejandra.", "(음성 메시지) 갈레고! 총괄 사장이라니! 우리 엄마가 로파 비에하 먹던 그 저녁부터 알았대. 그리고 이봐, 브리사스 대금은 전부 기한 내에 냈어. 알레한드라가 딴소리 못 하게."),
(A, "(ríe) Daniel pagando a tiempo. Eso sí que es una noticia.", "(웃으며) 다니엘이 제때 돈을 내다니. 그게 진짜 뉴스네요."),
(F, "(mensaje de voz) Querido Lucas: le felicito de corazón. Mi tío Saad dice que ya lo sabía: en una casa buena, el puesto acaba llegando a quien sabe decir que no. Que Dios le dé acierto.", "(음성 메시지) 친애하는 루카스, 진심으로 축하드립니다. 사드 삼촌이 이미 알았다고 하시네요. 좋은 집안에서는 결국 '아니요'라고 말할 줄 아는 사람에게 자리가 돌아간다고요. 하느님께서 당신의 판단을 지켜 주시기를."),
(L, "(en voz baja) El único que le dijo que no. Todavía se acuerda.", "(작은 목소리로) 자기한테 '아니요'라고 한 유일한 사람. 아직도 기억하네요."),
(A, "¿Y tú qué le vas a contestar?", "그럼 당신은 뭐라고 답할 거예요?"),
(L, "Que sin él no habríamos aprendido a esperar.", "그분이 없었으면 우린 기다리는 법을 못 배웠을 거라고."),
(K, "(mensaje de voz) Señor Ferrer, enhorabuena. Y sobre la pregunta que me hizo ayer: me duele, pero sí. Yu-na tiene que crecer, y en Seorin ya se le queda pequeño. Se la presto... para siempre.", "(음성 메시지) 페레르 씨, 축하드립니다. 그리고 어제 물어보신 일 말인데요. 마음이 아프지만, 좋습니다. 유나는 더 커야 해요. 서린은 이제 그 아이한테 작아요. 빌려 드릴게요… 영원히."),
(A, "¿«Prestada para siempre»? Eso suena a las ventosas que Pepe mandó a Monterrey.", "'영원히 빌려준다'? 페페가 몬테레이에 보낸 흡착기 얘기 같네요."),
(L, "Lo es. Y las ventosas siguen allí. Buena señal.", "맞아요. 그리고 그 흡착기는 아직도 거기 있어요. 좋은 징조죠."),
(None, "Lucas abre una videollamada. Aparece Yu-na en la oficina de Seorin, en Seúl. Detrás de ella, las luces de la ciudad.", "루카스가 영상통화를 연다. 서울 서린 사무실의 유나가 화면에 나타난다. 그녀 뒤로 도시의 불빛이 보인다."),
(Y, "Buenas tardes, señor Ferrer. Bueno, aquí son las ocho de la noche. Con tantos husos horarios, ya no sé qué decir.", "안녕하세요, 페레르 씨. 아, 여긴 밤 8시예요. 시차가 하도 많아서 무슨 인사를 해야 할지 모르겠어요."),
(L, "Buenas tardes aquí, buenas noches allí. Gracias por quedarte, Yu-na.", "여긴 오후, 거긴 밤이네요. 남아 줘서 고마워요, 유나."),
(Y, "La señora Kim me ha dicho que usted quería hablar conmigo. Y que no me preocupara. Eso me ha preocupado mucho.", "김 대표님이 페레르 씨가 저랑 얘기하고 싶어 하신다고, 걱정하지 말라고 하셨어요. 그 말 때문에 엄청 걱정했어요."),
(L, "(ríe) No es nada malo. Te voy a hacer una propuesta y quiero que la pienses con calma.", "(웃으며) 나쁜 일 아니에요. 제안을 하나 할 테니 천천히 생각해 봐요."),
(Y, "Dígame.", "말씀하세요."),
(L, "Albalat necesita a alguien para Asia. Corea, Singapur y lo que venga. Con base en Onda y viajando mucho. Te lo ofrezco a ti.", "알발라트에 아시아 담당이 필요해요. 한국, 싱가포르, 그리고 앞으로 생길 곳. 온다에 살면서 출장을 많이 다니는 자리예요. 그 자리를 당신에게 제안해요."),
(Y, "¿A mí? Pero yo trabajo para Seorin. La señora Kim...", "저한테요? 하지만 전 서린에서 일하는데요. 김 대표님이…"),
(L, "La señora Kim lo sabe. Se lo pregunté a ella antes que a ti. Dice que te presta para siempre.", "김 대표님도 알아요. 당신보다 그분께 먼저 물었어요. 당신을 영원히 빌려주겠대요."),
(Y, "(se tapa la boca) ¿Ha dicho eso? Ella nunca presta nada. Ni un bolígrafo.", "(입을 가리며) 그렇게 말씀하셨어요? 대표님은 아무것도 안 빌려주세요. 볼펜 하나도요."),
(A, "(se asoma a la pantalla) Hola, Yu-na. Soy Amparo. Te aviso de una cosa: en Onda no hay metro, se come a las dos y el café de la máquina es horrible.", "(화면에 얼굴을 내밀며) 안녕, 유나. 암파로예요. 하나 미리 말해 둘게요. 온다엔 지하철이 없고, 점심은 2시에 먹고, 자판기 커피는 끔찍해요."),
(Y, "En Valencia aprendí a comer a las dos. Lo del café... lo puedo soportar.", "발렌시아에서 2시에 점심 먹는 법은 배웠어요. 커피는… 참을 수 있어요."),
(L, "Las condiciones te las mando hoy por escrito. Sueldo, piso pagado los primeros seis meses y un billete a Seúl cada trimestre.", "조건은 오늘 서면으로 보낼게요. 급여, 첫 6개월 집세, 그리고 분기마다 서울행 항공권 한 장."),
(Y, "¿Y cuándo empezaría?", "그럼 언제부터 시작하는 거예요?"),
(L, "Cuando te venga bien. Pero si puede ser, el siete de septiembre. Es lunes. Los lunes son buenos para empezar.", "편한 때에요. 하지만 가능하면 9월 7일. 월요일이에요. 월요일은 시작하기 좋은 날이거든요."),
(Y, "¿Puedo serle sincera? La señora Kim me lo contó hace dos horas. He llamado a mi madre. Y mi madre me ha dicho: «¿España otra vez? Entonces ya sabes la respuesta».", "솔직하게 말씀드려도 될까요? 김 대표님이 두 시간 전에 얘기해 주셨어요. 엄마한테 전화했죠. 엄마가 그러셨어요. '또 스페인? 그럼 답은 이미 알잖아.'"),
(L, "¿Y cuál es la respuesta?", "그래서 답이 뭔데요?"),
(Y, "Sí. Acepto. El siete de septiembre estaré en Onda.", "네. 받아들일게요. 9월 7일에 온다에 가 있을게요."),
(A, "Pues bienvenida a la casa, Yu-na. Desde ya.", "그럼 우리 집에 온 걸 환영해요, 유나. 지금부터."),
(Y, "(sonríe) Gracias. Y enhorabuena por lo de director general, señor Ferrer. En Corea lo celebraríamos con una cena. Con soju.", "(미소 지으며) 감사합니다. 그리고 총괄 사장 되신 거 축하드려요, 페레르 씨. 한국이었으면 저녁 먹으면서 축하했을 거예요. 소주랑."),
(L, "Aquí lo celebramos con carajillo. Ya te enseñaremos.", "여기선 카라히요로 축하해요. 차차 가르쳐 줄게요."),
(None, "La pantalla se apaga. Lucas se levanta y escribe en la pizarra blanca, debajo del mapa: «7 de septiembre — Yu-na — primer día».", "화면이 꺼진다. 루카스가 일어나 지도 아래 화이트보드에 적는다. '9월 7일 — 유나 — 첫날'."),
(A, "¿Primer día?", "첫날?"),
(L, "Para ella. Y un poco para mí también.", "그녀에겐요. 그리고 저한테도 조금은요."),
(A, "(mira el mapa, luego a él) Socio.", "(지도를 보고, 그를 보며) 동업자."),
(L, "Socia.", "동업자."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
"가족 주주총회에서 매각이 65 대 35로 부결된 지 이틀. 월요일 아침, 루카스는 옛 상사이자 투자펀드 메리디아 캐피털의 파트너 보르하에게 전화해 대표이사 제안을 거절한다. 이어서 암파로와 '동업자 약속'을 새로 하고, 비센테와 라몬과 함께 새 직함과 증자를 정한다. 총괄 사장으로서 루카스의 첫 결정은 서울 서린의 한유나를 아시아 담당으로 데려오는 일이다. 다음 날 발표문이 나가자 몬테레이, 마이애미, 리야드, 서울에서 축하 메시지가 쏟아진다.",
"듣기 질문 ① 루카스는 보르하의 제안을 거절하면서 '숫자가 아니라 무엇'이 문제라고 하는가? 그가 남아서 얻는 두 가지는?",
"듣기 질문 ② 암파로가 동업자 약속에 새로 넣은 조항은 무엇인가?",
"듣기 질문 ③ 김민서의 음성 메시지에 나오는 '영원히 빌려준다'는 표현은 이 시리즈의 어떤 장면을 떠올리게 하는가?",
]),
]

